window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bd9a7b059771c434"]={"versions": [{"id": "FIG-bd9a7b059771c434", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des E2E-Profils 7 (AUTOSAR PRS E2EProtocol). Das Diagramm stellt den Teilschritt „Write CRC“ innerhalb der Funktionen <code>E2E_P07Protect()</code> und <code>E2E_P07Forward()</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Funktionen / Aufrufkontexte: <code>E2E_P07Protect()</code>, <code>E2E_P07Forward()</code> (als Unteraktivitäts-Icons dargestellt)\n</li><li>Variablen / Speicherstrukturen: Lokale Variable <code>CRC</code> (8 Byte / 64-Bit), Byte-Array <code>Data</code>\n</li><li>Adressierungs-Parameter: <code>Offset</code> (Offset innerhalb des Byte-Arrays <code>Data</code> für den Zielbereich <code>Data[Offset...Offset+7]</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Initialknoten (Startknoten).\n</li><li>Ausführung der Aktion „Copy 8-byte local variable CRC on bytes Data[Offset...Offset+7] using big Endian order“: Die 8 Byte der lokalen Variablen <code>CRC</code> werden in Big-Endian-Bytereihenfolge in das Daten-Array <code>Data</code> an den Indexpositionen von <code>Offset</code> bis <code>Offset+7</code> geschrieben.\n</li><li>Übergang in den Endknoten (Aktivitätsendknoten).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativer Teilschritt gemäß Anforderung [PRS_E2E_00493]. Bei der Implementierung ist sicherzustellen, dass die berechnete 64-Bit-CRC zwingend in Big-Endian-Reihenfolge (Most Significant Byte zuerst) in den durch <code>Offset</code> definierten 8-Byte-Puffer des Nutzdaten-Arrays kopiert wird. Beide E2E-Funktionen (<code>E2E_P07Protect</code> und <code>E2E_P07Forward</code>) teilen identisches Verhalten für diesen Schritt.</p>"}, {"id": "FIG-499e2a7089f4df9e", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des E2E-Profils 7 (AUTOSAR PRS E2EProtocol). Das Diagramm stellt den Teilschritt „Write CRC“ innerhalb der Funktionen <code>E2E_P07Protect()</code> und <code>E2E_P07Forward()</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Funktionen / Aufrufkontexte: <code>E2E_P07Protect()</code>, <code>E2E_P07Forward()</code> (als Unteraktivitäts-Icons dargestellt)\n</li><li>Variablen / Speicherstrukturen: Lokale Variable <code>CRC</code> (8 Byte / 64-Bit), Byte-Array <code>Data</code>\n</li><li>Adressierungs-Parameter: <code>Offset</code> (Offset innerhalb des Byte-Arrays <code>Data</code> für den Zielbereich <code>Data[Offset...Offset+7]</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Initialknoten (Startknoten).\n</li><li>Ausführung der Aktion „Copy 8-byte local variable CRC on bytes Data[Offset...Offset+7] using big Endian order“: Die 8 Byte der lokalen Variablen <code>CRC</code> werden in Big-Endian-Bytereihenfolge in das Daten-Array <code>Data</code> an den Indexpositionen von <code>Offset</code> bis <code>Offset+7</code> geschrieben.\n</li><li>Übergang in den Endknoten (Aktivitätsendknoten).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativer Teilschritt gemäß Anforderung [PRS_E2E_00493]. Bei der Implementierung ist sicherzustellen, dass die berechnete 64-Bit-CRC zwingend in Big-Endian-Reihenfolge (Most Significant Byte zuerst) in den durch <code>Offset</code> definierten 8-Byte-Puffer des Nutzdaten-Arrays kopiert wird. Beide E2E-Funktionen (<code>E2E_P07Protect</code> und <code>E2E_P07Forward</code>) teilen identisches Verhalten für diesen Schritt.</p>"}], "trans": [{"from": "FIG-bd9a7b059771c434", "to": "FIG-499e2a7089f4df9e", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
